import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

function createSession(): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
}

function createMockProvider(): AIProvider {
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'hi'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> { return {} as T; },
  };
}

const promptBuilder = new PromptBuilder({identity: 'test'});

describe('ChatOrchestrator beforeSession error handling', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const callOrder: string[] = [];
    const error = new Error('beforeSession failed');
    const hooks = {
      beforeSession: async () => {
        callOrder.push('beforeSession');
        throw error;
      },
      onError: async () => {
        callOrder.push('onError');
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(createSession())).rejects.toThrow('beforeSession failed');

    // This is expected to fail currently because onError and afterSession won't be in callOrder
    expect(callOrder).toEqual(['beforeSession', 'onError', 'afterSession']);
  });
});

